Vecindario 1: Or-opt general. Mueve un segmento de 1 a k clientes, opcionalmente invertido, a cualquier posición de cualquier ruta (incluida la propia) o a una ruta nueva.

```python
COMPONENT = {
    "name": "or_opt_segment_relocation",
    "slot": "neighborhood",
    "compatible_skeletons": ['SA', 'ILS', 'TS', 'VNS', 'GRASP', 'MIP_PERTURB'],
    "requires": ["ProblemModel.objective", "ProblemModel.parts"],
    "params": {
        "max_seg_len": {"type": "int", "range": [1, 3]},
        "allow_new_route": {"type": "bool", "values": [True, False]},
    },
}


class OrOptSegmentRelocation:
    """Movimiento = (r_src, start, length, r_dst, pos, rev).

    Extrae sol[r_src][start:start+length] (invertido si rev=1) y lo inserta en la posición `pos`
    de la ruta r_dst. Si r_dst == r_src, `pos` se mide sobre la ruta ya sin el segmento.
    Si r_dst == len(sol), el segmento forma una ruta nueva.
    """

    def __init__(self, problem, max_seg_len=3, allow_new_route=True):
        self.problem = problem
        self.canon = problem.parts.canonical
        self.max_seg_len = max(1, int(max_seg_len))
        self.allow_new_route = bool(allow_new_route)

    def _valid(self, sol, m):
        ri, s, l, rd, p, rev = m
        nR = len(sol)
        if not (0 <= ri < nR):
            return False
        L = len(sol[ri])
        if l < 1 or l > self.max_seg_len or s < 0 or s + l > L:
            return False
        if rev not in (0, 1) or (rev == 1 and l < 2):
            return False
        rest = L - l
        if rd == nR:
            return self.allow_new_route and rest > 0 and p == 0
        if not (0 <= rd < nR):
            return False
        if rd == ri:
            if not (0 <= p <= rest):
                return False
            if p == s and rev == 0:
                return False
            return True
        return 0 <= p <= len(sol[rd])

    def moves(self, sol):
        nR = len(sol)
        for ri, r in enumerate(sol):
            L = len(r)
            for s in range(L):
                for l in range(1, min(self.max_seg_len, L - s) + 1):
                    rest = L - l
                    for rev in ((0, 1) if l >= 2 else (0,)):
                        for rd in range(nR):
                            if rd == ri:
                                for p in range(rest + 1):
                                    if p == s and rev == 0:
                                        continue
                                    yield (ri, s, l, rd, p, rev)
                            else:
                                for p in range(len(sol[rd]) + 1):
                                    yield (ri, s, l, rd, p, rev)
                        if self.allow_new_route and rest > 0:
                            yield (ri, s, l, nR, 0, rev)

    def sample(self, sol, k, rng):
        out = []
        seen = set()
        nR = len(sol)
        if nR == 0:
            return out
        attempts = 0
        while len(out) < k and attempts < 30 * k + 50:
            attempts += 1
            ri = rng.randrange(nR)
            L = len(sol[ri])
            s = rng.randrange(L)
            l = rng.randint(1, min(self.max_seg_len, L - s))
            rev = rng.randint(0, 1) if l >= 2 else 0
            rest = L - l
            top = nR + (1 if (self.allow_new_route and rest > 0) else 0)
            rd = rng.randrange(top)
            if rd == nR:
                p = 0
            elif rd == ri:
                p = rng.randint(0, rest)
            else:
                p = rng.randint(0, len(sol[rd]))
            m = (ri, s, l, rd, p, rev)
            if m in seen or not self._valid(sol, m):
                continue
            seen.add(m)
            out.append(m)
        return out

    def apply(self, sol, m):
        ri, s, l, rd, p, rev = m
        routes = [list(r) for r in sol]
        seg = routes[ri][s:s + l]
        if rev:
            seg.reverse()
        del routes[ri][s:s + l]
        if rd == len(sol):
            routes.append(seg)
        else:
            tgt = routes[rd]
            routes[rd] = tgt[:p] + seg + tgt[p:]
        return self.canon(routes)

    def delta(self, sol, m):
        return self.problem.objective(self.apply(sol, m)) - self.problem.objective(sol)


def build_component(problem, max_seg_len=3, allow_new_route=True):
    return OrOptSegmentRelocation(problem, max_seg_len=max_seg_len, allow_new_route=allow_new_route)
```

Vecindario 2: 2-opt*. Intercambia las colas entre dos rutas, con una variante cruzada invertida; los cortes extremos fusionan rutas.

```python
COMPONENT = {
    "name": "two_opt_star_tail_exchange",
    "slot": "neighborhood",
    "compatible_skeletons": ['SA', 'ILS', 'TS', 'VNS', 'GRASP', 'MIP_PERTURB'],
    "requires": ["ProblemModel.objective", "ProblemModel.parts"],
    "params": {
        "allow_reverse": {"type": "bool", "values": [True, False]},
    },
}


class TwoOptStarTailExchange:
    """Movimiento = (a, b, i, j, v) con a < b índices de ruta y cortes 0<=i<=|A|, 0<=j<=|B|.

    v=0: A' = A[:i] + B[j:],        B' = B[:j] + A[i:]
    v=1: A' = A[:i] + rev(B[:j]),   B' = rev(A[i:]) + B[j:]
    Los cortes en los extremos permiten fusionar rutas completas (se omiten rutas vacías).
    """

    def __init__(self, problem, allow_reverse=True):
        self.problem = problem
        self.canon = problem.parts.canonical
        self.allow_reverse = bool(allow_reverse)

    def _trivial(self, sol, m):
        a, b, i, j, v = m
        la, lb = len(sol[a]), len(sol[b])
        if v == 0 and ((i == 0 and j == 0) or (i == la and j == lb)):
            return True
        return False

    def _valid(self, sol, m):
        a, b, i, j, v = m
        nR = len(sol)
        if not (0 <= a < b < nR):
            return False
        if not (0 <= i <= len(sol[a]) and 0 <= j <= len(sol[b])):
            return False
        if v not in ((0, 1) if self.allow_reverse else (0,)):
            return False
        return not self._trivial(sol, m)

    def moves(self, sol):
        nR = len(sol)
        vs = (0, 1) if self.allow_reverse else (0,)
        for a in range(nR):
            la = len(sol[a])
            for b in range(a + 1, nR):
                lb = len(sol[b])
                for i in range(la + 1):
                    for j in range(lb + 1):
                        for v in vs:
                            m = (a, b, i, j, v)
                            if self._trivial(sol, m):
                                continue
                            yield m

    def sample(self, sol, k, rng):
        out = []
        seen = set()
        nR = len(sol)
        if nR < 2:
            return out
        vs = (0, 1) if self.allow_reverse else (0,)
        attempts = 0
        while len(out) < k and attempts < 30 * k + 50:
            attempts += 1
            a, b = sorted(rng.sample(range(nR), 2))
            i = rng.randint(0, len(sol[a]))
            j = rng.randint(0, len(sol[b]))
            v = rng.choice(vs)
            m = (a, b, i, j, v)
            if m in seen or not self._valid(sol, m):
                continue
            seen.add(m)
            out.append(m)
        return out

    def apply(self, sol, m):
        a, b, i, j, v = m
        A, B = list(sol[a]), list(sol[b])
        if v == 0:
            na = A[:i] + B[j:]
            nb = B[:j] + A[i:]
        else:
            na = A[:i] + B[:j][::-1]
            nb = A[i:][::-1] + B[j:]
        routes = [list(r) for k2, r in enumerate(sol) if k2 != a and k2 != b]
        routes.append(na)
        routes.append(nb)
        return self.canon(routes)

    def delta(self, sol, m):
        return self.problem.objective(self.apply(sol, m)) - self.problem.objective(sol)


def build_component(problem, allow_reverse=True):
    return TwoOptStarTailExchange(problem, allow_reverse=allow_reverse)
